$inviteId..write:
auth != null && (
            // Création d'une nouvelle invitation
            (!data.exists() && newData.exists() && 
             newData.child('fromUserId').val() == auth.uid &&
             $inviteId.beginsWith(auth.uid + '_')) ||
            // Suppression par le destinataire (pour accepter/refuser)
            (data.exists() && !newData.exists() && auth.uid == $targetUserId) ||
            // Suppression par l'expéditeur (pour annuler)
            (data.exists() && !newData.exists() && data.child('fromUserId').val() == auth.uid)
          )

$roomId..write:
auth != null && (
          // Création
          (!data.exists() && newData.child('creatorId').val() == auth.uid) ||
          // Mise à jour par un participant
          (data.exists() && (
            data.child('creatorId').val() == auth.uid ||
            data.child('players/' + auth.uid).exists()
          )) ||
          // Suppression par le créateur
          (data.exists() && !newData.exists() && data.child('creatorId').val() == auth.uid)
        )
